  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (state === undefined) {
      this.states.set(key, { numerator: this.max, lastTick: tick })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      let numerator = state.numerator + this.refill * delta
      if (numerator > this.max) numerator = this.max
      state.numerator = numerator
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
