const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

/** Carries the failing line number and reason for a rejected limiter file. */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseUint(str, field, least, lineNo) {
  if (!UINT_RE.test(str) || BigInt(str) < BigInt(least)) {
    throw new ParseError(lineNo, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(str)
}

export function parseLimiterFile(text) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = new Map()
  const routeList = []
  const events = []
  let seenEvent = false
  let lastTick = null

  lines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    switch (directive) {
      case 'bucket': {
        if (tokens.length !== 5) {
          throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
        }
        const [, name, capStr, refillStr, perStr] = tokens
        if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
        const capacity = parseUint(capStr, 'capacity', 1, lineNo)
        const refill = parseUint(refillStr, 'refill', 0, lineNo)
        const per = parseUint(perStr, 'per', 1, lineNo)
        if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
        policies.set(name, { type: 'bucket', capacity, refill, per })
        break
      }
      case 'window': {
        if (tokens.length !== 4) {
          throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
        }
        const [, name, limitStr, spanStr] = tokens
        if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
        const limit = parseUint(limitStr, 'limit', 0, lineNo)
        const span = parseUint(spanStr, 'span', 1, lineNo)
        if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
        policies.set(name, { type: 'window', limit, span })
        break
      }
      case 'route': {
        if (tokens.length < 3) {
          throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
        }
        const prefix = tokens[1]
        const policyNames = tokens.slice(2)
        if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
        if (routes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
        for (const name of policyNames) {
          if (!policies.has(name)) throw new ParseError(lineNo, `unknown policy ${name}`)
        }
        const route = { prefix, policies: policyNames }
        routes.set(prefix, route)
        routeList.push(route)
        break
      }
      case 'event': {
        seenEvent = true
        if (tokens.length !== 3) {
          throw new ParseError(lineNo, 'expected event <tick> <key>')
        }
        const [, tickStr, key] = tokens
        const tick = parseUint(tickStr, 'tick', 0, lineNo)
