/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseLimiterFile, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
    return
  }

  const input = readFileSync(0, 'utf8')

  let model
  try {
    model = parseLimiterFile(input)
  } catch (error) {
    if (error instanceof ParseError) {
      fail(`line ${error.line}: ${error.reason}`)
      return
    }
    throw error
  }

  const result = simulate(model)
  const lines = []

  if (mode === 'replay') {
    for (const verdict of result.verdicts) {
      lines.push(
        verdict.allowed
          ? `${verdict.tick} ${verdict.key} allow`
          : `${verdict.tick} ${verdict.key} deny ${verdict.denyPolicy}`,
      )
    }
  } else {
    const keys = [...result.perKey.keys()].sort()
    for (const key of keys) {
      const tally = result.perKey.get(key)
      lines.push(`${key} allowed=${tally.allowed} denied=${tally.denied}`)
    }
    lines.push(`total allowed=${result.totalAllowed} denied=${result.totalDenied}`)
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
}

main()
"}

